//! Reader-release frames: each affected record carries every applicable hook member, including
//! the final input where no rendered field holds it. These are fixed complete frames, not
//! snapshots regenerated by the encoder under test.

use super::{FrozenDeclaration, HookOp, Hooks, OpaqueJson, WalRecord};
use crate::framing::{decode_next, encode, DecodeStep, STEP_TRANSFORMS_FEATURE};
use serde::Deserialize;
use serde_json::{json, Value};

#[derive(Deserialize)]
struct Golden {
    requires: Vec<String>,
    record: WalRecord,
}

const GOLDENS: &[(&str, &str)] = &[
    (
        include_str!("../../tests/golden/step_transforms/run_started.json"),
        include_str!("../../tests/golden/step_transforms/run_started.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/queued.json"),
        include_str!("../../tests/golden/step_transforms/queued.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/steered.json"),
        include_str!("../../tests/golden/step_transforms/steered.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/model_step_finished.json"),
        include_str!("../../tests/golden/step_transforms/model_step_finished.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/tool_dispatch_intent.json"),
        include_str!("../../tests/golden/step_transforms/tool_dispatch_intent.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/tool_no_dispatch.json"),
        include_str!("../../tests/golden/step_transforms/tool_no_dispatch.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/tool_result.json"),
        include_str!("../../tests/golden/step_transforms/tool_result.frame.hex"),
    ),
    (
        include_str!("../../tests/golden/step_transforms/tool_result_deny.json"),
        include_str!("../../tests/golden/step_transforms/tool_result_deny.frame.hex"),
    ),
];

fn hooks(record: &WalRecord) -> &Hooks {
    match record {
        WalRecord::RunStarted { hooks, .. }
        | WalRecord::Queued { hooks, .. }
        | WalRecord::Steered { hooks, .. }
        | WalRecord::ModelStepFinished { hooks, .. }
        | WalRecord::ToolDispatchIntent { hooks, .. }
        | WalRecord::ToolNoDispatch { hooks, .. }
        | WalRecord::ToolResult { hooks, .. } => hooks.as_ref().expect("golden carries hooks"),
        other => panic!("unexpected hooked kind: {other:?}"),
    }
}

fn input(text: &str) -> Value {
    json!([{"role":"user","content":[{"type":"text","text":text}]}])
}

#[test]
fn every_step_transform_golden_frame_decodes_with_all_members() {
    let subjects = [
        (
            Some(input("hello")),
            None,
            "pre_user",
            None,
            "append",
            "add reminder",
        ),
        (
            None,
            Some(input("queued transformed")),
            "pre_user",
            None,
            "append",
            "add reminder",
        ),
        (
            Some(input("write up now")),
            None,
            "pre_user",
            None,
            "append",
            "add reminder",
        ),
        (
            Some(
                json!({"message_id":"msg-3","content":[{"type":"text","text":"ok"},{"type":"tool_call","tool_call_id":"t1","tool_name":"edit","input":{"f":"a"}}]}),
            ),
            None,
            "post_assistant",
            None,
            "append",
            "add reminder",
        ),
        (
            Some(json!({"f":"a"})),
            None,
            "pre_tool",
            Some("mutate"),
            "mutate",
            "restrict input",
        ),
        (
            Some(json!({"f":"a"})),
            Some(json!({"f":"b"})),
            "pre_tool",
            Some("mutate"),
            "mutate",
            "restrict input",
        ),
        (
            Some(
                json!({"tool_call_id":"t1","output":{"kind":"text","text":"done"},"is_error":false}),
            ),
            None,
            "post_tool",
            None,
            "append",
            "add reminder",
        ),
        (
            Some(json!({"f":"a"})),
            Some(json!({"f":"b"})),
            "pre_tool",
            Some("validate"),
            "deny",
            "deny input",
        ),
    ];
    assert_eq!(GOLDENS.len(), subjects.len());
    for ((json, hex), (original, final_value, hook, phase, op, note)) in
        GOLDENS.iter().zip(subjects)
    {
        let golden: Golden = serde_json::from_str(json).unwrap();
        assert_eq!(golden.record.required_features(), golden.requires);
        assert_eq!(
            hooks(&golden.record),
            &Hooks {
                original,
                final_value,
                ops: vec![HookOp {
                    module: "magic-context".into(),
                    hook: hook.into(),
                    phase: phase.map(str::to_owned),
                    op: op.into(),
                    block: Some(0),
                    note: Some(note.into()),
                }],
                unavailable: Some(vec!["notes".into()]),
            }
        );
        assert_eq!(hex.trim_end().len() % 2, 0);
        let pinned: Vec<u8> = hex
            .trim_end()
            .as_bytes()
            .as_chunks::<2>()
            .0
            .iter()
            .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
            .collect();
        let encoded = encode(7, 11, &golden.record).unwrap();
        assert_eq!(encoded, pinned, "golden frame bytes changed");
        assert_eq!(
            &encoded[crate::framing::HEADER_LEN..],
            json.trim_end().as_bytes()
        );
        let DecodeStep::Record { framed, consumed } = decode_next(&pinned) else {
            panic!("hooked golden must decode: {json}");
        };
        assert_eq!(consumed, pinned.len());
        assert_eq!((framed.seq, framed.fence), (7, 11));
        assert_eq!(framed.record, golden.record);
    }
}

fn frozen() -> FrozenDeclaration {
    FrozenDeclaration {
        provider: "magic-context".into(),
        answer: OpaqueJson::from_json_text(
            r#"{"z":1,"a":2.50,"big":100000000000000000000,"e":1e3,"s":"\u00e9"}"#,
        )
        .unwrap(),
    }
}

#[test]
fn frozen_declarations_keep_verbatim_answers_and_plan_order() {
    let Golden { mut record, .. } = serde_json::from_str(GOLDENS[0].0).unwrap();
    let WalRecord::RunStarted {
        manifest: Some(ref mut manifest),
        ..
    } = record
    else {
        panic!("run golden has a manifest");
    };
    assert_eq!(manifest.declarations, vec![frozen()]);
    assert!(
        manifest.fetches.is_empty(),
        "a step-only provider is not a fetch"
    );
    let mut second = frozen();
    second.provider = "a-provider".into();
    manifest.declarations.push(second.clone());
    let encoded = encode(1, 1, &record).unwrap();
    let DecodeStep::Record { framed, .. } = decode_next(&encoded) else {
        panic!("must decode")
    };
    let WalRecord::RunStarted {
        manifest: Some(manifest),
        ..
    } = framed.record
    else {
        panic!("manifest")
    };
    assert_eq!(manifest.declarations, vec![frozen(), second]);
}

#[test]
fn run_started_requires_transforms_for_hooks_or_nonempty_declarations_in_sorted_order() {
    use crate::framing::{FLOW_SCOPE_FEATURE, PLAN_MANIFEST_FEATURE, SCOPE_FEATURE};
    for scope_kind in 0..3 {
        for with_manifest in [false, true] {
            for with_hooks in [false, true] {
                for with_declarations in [false, true] {
                    if with_declarations && !with_manifest {
                        continue;
                    }
                    let Golden { mut record, .. } = serde_json::from_str(GOLDENS[0].0).unwrap();
                    let WalRecord::RunStarted {
                        scope,
                        manifest,
                        hooks,
                        ..
                    } = &mut record
                    else {
                        unreachable!()
                    };
                    *scope = match scope_kind {
                        0 => None,
                        1 => Some(serde_json::from_value(json!({"owner":{"kind":"direct"},"ref":"scope-1","scope_epoch":1})).unwrap()),
                        _ => Some(serde_json::from_value(json!({"owner":{"kind":"direct"},"ref":"scope-1","scope_epoch":1,"flow_id":"flow-1"})).unwrap()),
                    };
                    if with_manifest {
                        manifest.as_mut().unwrap().declarations = if with_declarations {
                            vec![frozen()]
                        } else {
                            vec![]
                        };
                    } else {
                        *manifest = None;
                    }
                    if !with_hooks {
                        *hooks = None;
                    }
                    let mut expected = Vec::new();
                    if scope_kind == 2 {
                        expected.push(FLOW_SCOPE_FEATURE);
                    }
                    if with_manifest {
                        expected.push(PLAN_MANIFEST_FEATURE);
                    }
                    if scope_kind != 0 {
                        expected.push(SCOPE_FEATURE);
                    }
                    if with_hooks || with_declarations {
                        expected.push(STEP_TRANSFORMS_FEATURE);
                    }
                    assert_eq!(record.required_features(), expected, "scope={scope_kind}, manifest={with_manifest}, hooks={with_hooks}, declarations={with_declarations}");
                }
            }
        }
    }
}

#[test]
fn every_hooks_member_requires_transforms_even_without_ops() {
    for (json, _) in GOLDENS {
        let Golden { mut record, .. } = serde_json::from_str(json).unwrap();
        let slot = match &mut record {
            WalRecord::RunStarted {
                hooks, manifest, ..
            } => {
                *manifest = None;
                hooks
            }
            WalRecord::Queued { hooks, .. }
            | WalRecord::Steered { hooks, .. }
            | WalRecord::ModelStepFinished { hooks, .. }
            | WalRecord::ToolNoDispatch { hooks, .. }
            | WalRecord::ToolResult { hooks, .. } => hooks,
            WalRecord::ToolDispatchIntent {
                hooks,
                module_id,
                schema_pin,
                ..
            } => {
                *module_id = None;
                *schema_pin = None;
                hooks
            }
            _ => unreachable!(),
        };
        *slot = Some(Box::new(Hooks {
            original: None,
            final_value: None,
            ops: vec![],
            unavailable: None,
        }));
        assert!(record
            .required_features()
            .contains(&STEP_TRANSFORMS_FEATURE));
    }
}

#[test]
fn absent_and_empty_declarations_write_no_bytes() {
    let bytes =
        include_str!("../../tests/golden/pre_step_transforms/plan_manifest.json").trim_end();
    let record: WalRecord = serde_json::from_str(bytes).unwrap();
    let WalRecord::RunStarted {
        manifest: Some(manifest),
        hooks,
        ..
    } = &record
    else {
        panic!("manifest")
    };
    assert!(hooks.is_none());
    assert!(manifest.declarations.is_empty());
    assert_eq!(serde_json::to_string(&record).unwrap(), bytes);
    let mut explicit: Value = serde_json::from_str(bytes).unwrap();
    explicit["manifest"]["declarations"] = json!([]);
    let decoded: WalRecord = serde_json::from_value(explicit).unwrap();
    assert_eq!(decoded, record);
    assert_eq!(serde_json::to_string(&decoded).unwrap(), bytes);
}

#[test]
fn nullable_hook_subjects_and_optional_attribution_round_trip() {
    for bytes in [
        r#"{"ops":[]}"#,
        r#"{"original":null,"final":null,"ops":[]}"#,
        r#"{"ops":[{"module":"future-provider","hook":"future-hook","phase":"future-phase","op":"future-op"}]}"#,
    ] {
        let decoded: Hooks = serde_json::from_str(bytes).unwrap();
        assert_eq!(serde_json::to_string(&decoded).unwrap(), bytes);
    }
    let decoded: Hooks =
        serde_json::from_str(r#"{"original":null,"final":null,"ops":[]}"#).unwrap();
    assert_eq!(decoded.original, Some(Value::Null));
    assert_eq!(decoded.final_value, Some(Value::Null));
}
